const d = {"name":"Endeavour","label":"Label_5823373004158048354","skip":"Thank you for your Application Submission"};
const rule = ({"_about":"How MTR – 03 finds the network approval letter among a deal's HubSpot attachments (file names, case-insensitive regex). Newest match wins. A note starting 'Network approval' (written by MTR – 05) is also accepted.","Ausgrid":{"fileName":"^Notification Letter","_note":"Confirmed by Rodrigo 23 Sep 2026: the Notification Letter is the approval retailers need."},"Endeavour":{"fileName":"_PTC_","_note":"Same rule as the Endeavour PTC workflow"},"Essential":{"fileName":null,"_note":"Rare. No file name rule yet: Essential deals hold until the letter is attached as a note starting \"Network approval\"."}})[d.name] || {};
const re = rule.fileName ? new RegExp(rule.fileName, 'i') : null;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const subject = j.subject || j.headers?.subject || '';
  if (d.skip && subject.includes(d.skip)) continue;
  const bin = item.binary || {};
  const pdfs = Object.keys(bin).filter((k) => /pdf/i.test(bin[k].mimeType || '') || /\.pdf$/i.test(bin[k].fileName || ''));
  // With a file-name rule, only the matching PDF is the approval; otherwise the first PDF.
  const key = re ? pdfs.find((k) => re.test(bin[k].fileName || '')) : pdfs[0];
  if (!key) continue;
  out.push({ json: { distributor: d.name, subject, messageId: j.id, fileName: bin[key].fileName }, binary: { letter: bin[key] } });
}
return out;

